import{z as A,x as i,o as l,c as d,q as B,j as t,D as r,d as e,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"递归与栈帧","description":"","frontmatter":{"title":"递归与栈帧","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/recursion-stack-frame.md","filePath":"cs/recursion-stack-frame.md","lastUpdated":1791063341000}'),p={name:"cs/recursion-stack-frame.md"};function c(C,a,m,u,h,D){const n=i("Mermaid");return l(),d("div",null,[a[2]||(a[2]=B('<h1 id="递归与栈帧" tabindex="-1">递归与栈帧 <a class="header-anchor" href="#递归与栈帧" aria-label="Permalink to &quot;递归与栈帧&quot;">​</a></h1><div class="epigraph"><p>每一次尚未返回的调用都占一帧；递归把同一函数的许多帧叠在栈上，深度就是还没付清的调用次数。</p><footer>—— 据 Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective；Kernighan &amp; Ritchie, The C Programming Language, 2nd ed. 整理</footer></div><p>上一课<a href="/cs/calling-convention-preview">调用约定直觉</a>钉死了：一次调用靠 ABI 交接参数与返回地址。本课不重讲寄存器表，也不从数学归纳法另起。缺口是：同一函数被再次进入时，<strong>旧的局部变量到哪去了</strong>？为何递归能「同时」拥有许多份 <code>n</code>，以及这份能力的上限在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>调用约定已经保证：进入 callee 时有新的参数槽与返回地址。递归只是 callee 碰巧等于 caller 的函数。每一层仍按同一协议建帧：局部自动变量、保存的寄存器、返回地址。缺口因此不是「递归语法」，而是<strong>帧与调用一一对应</strong>：尚未返回的调用次数等于活着的帧数；返回时只弹出最上面一帧，外层的局部完好。</p><p>把递归理解成「函数改自己的全局状态」会立刻写错：那是在静态存储上叠状态，层与层互相踩。栈帧给出的是按深度隔离的自动存储。树遍历、分治、表达式求值都靠这一隔离；它们的共同点是等待子调用返回后再用本层的局部。</p><p><span class="marginnote">直觉类比：栈帧像摞盘子——每次调用往顶上放一个新盘子（新的一份局部变量），每个盘子上写着自己的 <code>n</code>；返回时只拿走最上面的盘子，下面每个盘子上的字完好无损。递归的全部魔力就是「每个盘子有自己的便签」，而循环只是反复擦写同一张便签。</span></p><h3 id="递归不是「比较慢的循环」" tabindex="-1">递归不是「比较慢的循环」 <a class="header-anchor" href="#递归不是「比较慢的循环」" aria-label="Permalink to &quot;递归不是「比较慢的循环」&quot;">​</a></h3><p>循环在同一帧里改局部；递归每层一帧，额外付出调用与返回。尾递归在某些语言里可以复用帧，C 并不保证这种消除。把递归等价于循环，会看不见栈上限：循环计数器溢出是整数问题，递归过深是栈溢出，两者的失败模式不同，后课未定义行为与信号会分开处理。</p><p><span class="marginnote">CSAPP 用栈帧图解释递归阶乘与深调用。K&amp;R 指出自动变量在每次进入时新生。本课不把 Y 组合子或闭包转换请进来，那是另一套编译课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一帧通常含：返回地址、callee-saved 寄存器、局部与临时、对齐填充、可能的溢出参数区。递归深度 \\(d\\) 则栈上约有 \\(d\\) 帧。帧大小由局部数组与编译器决定，不由「递归」这个词决定：局部若有大数组，几层就会碰上限。</p><p><span class="marginnote">数字实例：Linux 线程默认栈 8MB。阶乘每帧约 48–64 字节，能扛约 13 万层；但帧里若有个 <code>char buf[8192]</code>，每帧 8KB 出头，约 1000 层就把栈吃光。同一算法、同一深度，帧大小差两个数量级——决定生死的从来是局部变量，不是递归这个词。</span></p>',13)),(l(),t(s,null,{default:r(()=>[o(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E5%B8%A7%EF%BC%9An%20%E7%AD%89%E4%BA%8E%203%EF%BC%8C%E7%AD%89%E5%BE%85%E5%AD%90%E8%B0%83%E7%94%A8%22%5D%20--%3E%20C2%5B%22%E5%B8%A7%EF%BC%9An%20%E7%AD%89%E4%BA%8E%202%22%5D%0A%20%20C2%20--%3E%20C3%5B%22%E5%B8%A7%EF%BC%9An%20%E7%AD%89%E4%BA%8E%201%EF%BC%8C%E5%88%B0%E8%BE%BE%E5%9F%BA%E5%87%86%22%5D%0A%20%20C3%20--%3E%20R2%5B%22%E8%BF%94%E5%9B%9E%E5%88%B0%20n%20%E7%AD%89%E4%BA%8E%202%22%5D%0A%20%20R2%20--%3E%20R1%5B%22%E8%BF%94%E5%9B%9E%E5%88%B0%20n%20%E7%AD%89%E4%BA%8E%203%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"基准情形必须在有限步内到达，否则帧一直增长直到栈耗尽。互相递归只是若干函数交替建帧，机制相同。通过指针把本层局部交给子调用是合法的，只要子调用返回前不用这些指针——寿命规则下一课才总括，本课先看见：子帧活着时，父帧也还活着。",-1)),a[4]||(a[4]=E("p",null,"互递归、间接递归（经函数指针）不改变「一调用一帧」。函数指针让 callee 在运行时才确定，帧的大小按真正进入的那个函数来。可变长度局部数组让帧大小成为运行时量，栈预算更难在编译期看见。这些都是深度资源的变体。后课把越出帧寿命、越出对象边界的事收成未定义行为；栈映射本身耗尽则通常先变成操作系统终止，程序员不能把它当成返回码来检查。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,[e("栈向固定方向增长（常见向低地址）。操作系统给的栈资源有上限，越过则典型地收到信号或直接终止。这与堆的 "),E("code",null,"malloc"),e(" 失败不同：栈扩展往往不可在用户代码里「检查返回值」。因此递归算法必须有深度预算，或改成显式堆上的栈/队列。")],-1)),a[7]||(a[7]=E("p",null,"同一函数的不同帧可以别名吗？可以，若你把内层指针传到外层并在返回后使用——那时内层已死。活着的嵌套期间，内层指向外层局部是常见模式（输出参数）。帧提供隔离，指针可以主动打破隔离；打破之后寿命由程序员负责。",-1)),(l(),t(s,null,{default:r(()=>[o(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%87%BD%E6%95%B0%E6%89%93%E7%AE%97%E9%80%92%E5%BD%92%22%5D%20--%3E%20Q%7B%22%E6%B7%B1%E5%BA%A6%E5%8F%AF%E6%8E%A7%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9C%89%E7%95%8C%E4%B8%94%E5%9F%BA%E5%87%86%E5%8F%AF%E8%BE%BE%22%7C%20OK%5B%22%E9%A2%84%E7%AE%97%E5%86%85%E8%B7%91%E5%AE%8C%EF%BC%9A%E8%BF%94%E5%9B%9E%E8%87%AA%E5%8A%A8%E5%BC%B9%E5%B8%A7%22%5D%0A%20%20Q%20--%3E%7C%22%E6%B7%B1%E5%BA%A6%E7%94%B1%E8%BE%93%E5%85%A5%E5%86%B3%E5%AE%9A%22%7C%20CK%7B%22%E8%BF%9B%E5%85%A5%E5%89%8D%E6%9C%89%E6%B7%B1%E5%BA%A6%E9%A2%84%E7%AE%97%E5%90%97%EF%BC%9F%22%7D%0A%20%20CK%20--%3E%7C%22%E6%9C%89%E9%A2%84%E7%AE%97%22%7C%20G%5B%22%E8%B6%85%E9%99%90%E6%94%B9%E7%94%A8%E5%A0%86%E4%B8%8A%E7%9A%84%E6%98%BE%E5%BC%8F%E6%A0%88%22%5D%0A%20%20CK%20--%3E%7C%22%E6%97%A0%E9%A2%84%E7%AE%97%22%7C%20SO%5B%22%E5%B8%A7%E6%8C%81%E7%BB%AD%E5%A2%9E%E9%95%BF%EF%BC%9A%E6%A0%88%E6%98%A0%E5%B0%84%E8%80%97%E5%B0%BD%22%5D%0A%20%20SO%20--%3E%20CR%5B%22%E8%BF%9B%E7%A8%8B%E6%94%B6%E5%88%B0%E4%BF%A1%E5%8F%B7%E6%88%96%E7%9B%B4%E6%8E%A5%E7%BB%88%E6%AD%A2%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=B('<p><span class="marginnote">常见误区：初学者容易把栈溢出当普通异常，想用返回码或 try-catch 兜住。栈耗尽发生在「为下一帧腾地方」的瞬间，用户代码往往连一条指令都执行不到，典型结局是信号或进程直接终止——它和 <code>malloc</code> 返回 NULL 是两种完全不同的失败模式，只能在进入递归前做预算检查。</span></p><p>调试器里看到的回溯，正是这些尚未返回的帧串成的链：每一行对应一个返回地址槽。优化后的尾调用可能复用帧，回溯变短，源码里的「递归」在机器上变成跳转——C 不保证发生。相反，未优化时过大的局部数组会让两三次调用就耗尽映射。本课把深度当资源：算法选递归，等于选了栈预算。后课未定义行为会把「用完已经返回的帧」收成悬挂；溢出栈本身通常先变成操作系统信号，再表现为崩溃，而不是一个有定义的错误码。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲协程如何把帧搬到堆上，不讲内联如何消去调用。下一课<a href="/cs/undefined-behavior">未定义行为</a>把「越出抽象机器」总括成语言契约。后课默认：每次调用一帧；递归深度受栈限制；返回后该帧上的自动对象结束寿命。</p><p>基准情形必须在源码里可见且可达，不能靠「栈总会用完」当终止条件。深度由输入决定时，要在进入递归前检查预算，或改成堆上的显式栈。帧图与调用约定一致：返回只弹出当前层，外层局部仍在。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>尚未返回的调用各占一帧；递归是同一函数的多层帧。</li><li>层与层的局部互不覆盖，除非用指针主动共享。</li><li>深度受栈上限约束，失败模式不同于循环。</li><li>下一课把越界、溢出、非法指针收成未定义行为。</li><li>出处：CSAPP 栈帧；K&amp;R 自动变量的寿命。</li></ul>',7))])}const g=A(p,[["render",c]]);export{F as __pageData,g as default};
